// Synthetic fixture is generated by pob-item-controls-smoke; no personal input is loaded.
const {_electron:electron}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
require('tsx/cjs');const {createDefaultState,createBuildDocument}=require('../src/shared/state.ts'),{editBuild,parseBuild}=require('../src/shared/pob-document.ts');
const fixture=JSON.parse(fs.readFileSync('.local/standalone-pob/item-controls-fixture.json','utf8')),measurements=JSON.parse(fs.readFileSync('.local/standalone-pob/item-controls-result.json','utf8'));assert(!measurements.error);
const root=path.resolve('.'),directory=path.join(root,'.local','item-controls-native-'+Date.now()),executable=process.env.POK_SMOKE_EXECUTABLE;fs.mkdirSync(path.join(directory,'resources'),{recursive:true});for(const name of ['pob-runtime','pob-editor'])fs.symlinkSync(path.join(root,'resources',name),path.join(directory,'resources',name),'junction');
const a=createBuildDocument('Synthetic Item A',fixture.xml),b=createBuildDocument('Synthetic Item B',fixture.xml),loss=createBuildDocument('Synthetic Source Loss',editBuild(fixture.xml,{type:'item',id:'1',text:fixture.text+'\n<future item line>'})),legacy=createBuildDocument('Synthetic Legacy Range',editBuild(fixture.xml,{type:'item',id:'1',text:'Rarity: RARE\nSynthetic Ranged Armour\nRusted Cuirass\n--------\n+(5-15) to Dexterity'}).replace('</Item>','<ModRange id="1" range="0"/></Item>'));const initial=createDefaultState();initial.builds=[a,b,loss,legacy];initial.activeBuildId=a.id;initial.settings.pok.autoConnect=false;fs.mkdirSync(path.join(directory,'workspace'));fs.writeFileSync(path.join(directory,'workspace','workspace.v1.json'),JSON.stringify(initial));
const env={...process.env,POK_UI_DATA_DIR:directory,POK_UI_RESOURCE_DIR:path.join(directory,'resources')};delete env.ELECTRON_RUN_AS_NODE;delete env.POK_RENDERER_URL;
let app,page;const report={at:new Date().toISOString(),passed:[]};const state=()=>page.evaluate(()=>window.pok.loadState()),current=async()=>{const s=await state();return s.builds.find(b=>b.id===s.activeBuildId);};
async function poll(read,test){const end=Date.now()+120000;let value;do{value=await read();if(test(value))return value;await page.waitForTimeout(200);}while(Date.now()<end);throw new Error('Poll timed out: '+JSON.stringify(value));}
async function launch(){app=await electron.launch({executablePath:executable||path.join(root,'node_modules','electron','dist','electron.exe'),args:executable?[]:[root],cwd:directory,env,timeout:90000});page=await app.firstWindow();page.setDefaultTimeout(90000);await page.locator('.app-shell').waitFor();report.packaged=await app.evaluate(({app})=>app.isPackaged);if(executable)assert(report.packaged);}
async function open(){await page.locator('.slot-row').filter({hasText:'갑옷'}).click();await page.getByText('원본 아이템 옵션',{exact:true}).click();await page.getByLabel('원본 Quality',{exact:true}).waitFor();}
async function ready(){await poll(()=>page.getByLabel('원본 Quality',{exact:true}).isEnabled(),Boolean);}
async function change(label,value){const input=page.getByLabel(label,{exact:true});await input.fill(value);await input.press('Tab');await ready();await poll(()=>input.inputValue(),v=>v===value);}
(async()=>{
  await launch();await page.locator('.slot-row').filter({hasText:'투구'}).click();await page.getByRole('button',{name:'Synthetic Armour 장착',exact:true}).click();await page.getByText(/Original PoB rejected this item for slot Helmet/).waitFor();assert.equal((await current()).xml,fixture.xml);assert.equal((await current()).revision,0);
  report.passed.push('stored library equipment cannot bypass original slot validation or mutate the input after rejection');
  await open();await ready();await change('원본 Quality','20');assert.equal((await current()).xml,fixture.xml);assert.equal((await current()).revision,0);
  await page.getByLabel('현재 빌드',{exact:true}).selectOption(b.id);await open();await ready();assert.equal(await page.getByLabel('원본 Quality',{exact:true}).inputValue(),'0');assert.equal((await current()).xml,fixture.xml);assert.equal((await state()).builds.find(x=>x.id===a.id).revision,0);
  report.passed.push('detached native option preview leaves the canonical XML unchanged and never leaks into another identical document');
  await page.getByLabel('현재 빌드',{exact:true}).selectOption(a.id);await open();await ready();await change('원본 Quality','20');await change('원본 Augment Sockets','1');await page.getByLabel('원본 Rune 1',{exact:true}).selectOption({label:fixture.rune.name+' · '+fixture.rune.label});await ready();await poll(()=>page.getByRole('button',{name:'아이템 옵션 적용·새 계산',exact:true}).isEnabled(),Boolean);assert.equal((await current()).revision,0);
  for(const [width,height] of [[1920,1080],[1024,768]]){await app.evaluate(({BrowserWindow},size)=>BrowserWindow.getAllWindows()[0].setContentSize(...size),[width,height]);await page.getByText('원본 아이템 옵션',{exact:true}).scrollIntoViewIfNeeded();assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.screenshot({path:path.join(directory,'item-options-'+width+'.png')});}
  await page.getByRole('button',{name:'아이템 옵션 적용·새 계산',exact:true}).click();let saved=await poll(current,x=>x.revision===1&&x.calculation?.revision===1);assert.equal(saved.calculation.result.stats.Armour,fixture.armour.quality);assert.equal(saved.calculation.result.stats.Dex,measurements.dex.after);assert(saved.calculation.result.editor_diagnostics.diagnostics.some(d=>d.code==='item-unparsed-lines'));assert(parseBuild(saved.xml).items[0].text.includes(fixture.unsupported));assert.match(saved.xml,/<FutureItem value="keep"/);assert.equal(saved.originalXml,fixture.xml);
  report.passed.push('quality, socket and native-named rune apply as one revision, preserve unsupported Korean/XML metadata, and reach a calculation with stored diagnostics');
  await page.getByRole('button',{name:'되돌리기',exact:true}).click();saved=await poll(current,x=>x.revision===2);assert.equal(saved.xml,fixture.xml);await ready();assert.equal(await page.getByLabel('원본 Quality',{exact:true}).inputValue(),'0');
  await app.close();app=undefined;await launch();assert.equal((await current()).xml,saved.xml);assert.equal((await current()).originalXml,fixture.xml);assert.equal((await page.evaluate(()=>window.pok.getPokConnection())).connected,false);
  report.passed.push('undo and restart restore the exact input while retaining revision ownership without PoK');
  await page.getByLabel('현재 빌드',{exact:true}).selectOption(legacy.id);await open();await ready();await change('원본 Quality','20');await page.getByText(/\{range:0\}/).first().waitFor();assert.equal((await current()).revision,0);await page.getByRole('button',{name:'아이템 옵션 적용·새 계산',exact:true}).click();const ranged=await poll(current,x=>x.revision===1&&x.calculation?.revision===1);assert.equal(ranged.calculation.result.stats.Dex,measurements.legacyDex);assert.match(ranged.xml,/<ModRange id="1" range="0"/);
  report.passed.push('an unrelated quality edit starts from restored legacy ModRange state and retains its actual calculated roll');
  await page.getByLabel('현재 빌드',{exact:true}).selectOption(loss.id);await open();await page.getByText('원본 줄 일부를 정확히 보존하지 못해 적용을 차단했습니다. 현재 아이템 원문은 변경되지 않았습니다.',{exact:true}).waitFor();assert(await page.getByLabel('원본 Quality',{exact:true}).isDisabled());assert.equal(await page.getByRole('button',{name:'아이템 옵션 적용·새 계산',exact:true}).count(),0);assert.equal((await current()).xml,loss.xml);assert.equal((await current()).revision,0);
  report.passed.push('a native sanitisation loss blocks editing/application and preserves the complete source instead of silently dropping it');
})().catch(async error=>{report.error=error.stack;process.exitCode=1;if(page)await page.screenshot({path:path.join(directory,'failure.png')}).catch(()=>{});}).finally(async()=>{if(app)await app.close();fs.writeFileSync(path.join(directory,'result.json'),JSON.stringify(report,null,2));console.log(directory);if(report.error)console.error(report.error);});
